"""Import bounded owned resource template/action metadata for actual662DB0."""
import argparse,hashlib,json,struct
from pathlib import Path
ROOT=Path(__file__).resolve().parents[3]
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
def main():
 p=argparse.ArgumentParser();p.add_argument('--output',type=Path,required=True);a=p.parse_args();out=a.output.resolve();assert not out.exists()and out.is_relative_to(ROOT/'build-native-sjuni');out.mkdir()
 image=ROOT/'build-function-index/owned-overlays/o2.bin';assert sha(image)=='45360a971e88878312576abaebd1a7b8346f7e94cc032adde9172343f14e6226';raw=image.read_bytes();read=lambda at,size:raw[at-0x570000:at-0x570000+size]
 floats=lambda at:'{'+','.join('std::bit_cast<float>(0x%08xu)'%v for v in struct.unpack('<3I',read(at,12)))+'}'
 rows=[]
 for i in range(64):
  at=0x719a60+68*i;kind=read(at+5,1)[0];offsets=[floats(at+16+12*j)for j in range(2)];angles=['{'+','.join(str(v)for v in struct.unpack('<3H',read(at+40+8*j,6)))+'}'for j in range(2)];rows.append('    AttachmentMetadata{'+str(kind)+',{{'+','.join(offsets)+'}},{{'+','.join(angles)+'}}}')
 text='// Exact bounded File1 o2 metadata; generated by qualify_attachment_profile_v1.py.\nconstexpr std::array<AttachmentMetadata,64> action_metadata{{\n'+',\n'.join(rows)+'\n}};\n'
 target=ROOT/'game/native/gameplay_world/attachment_profile.inc';assert not target.exists();target.write_text(text);(out/'attachment_profile.inc').write_bytes(target.read_bytes())
 r=dict(schema=1,status='passed',source_image={'path':image.relative_to(ROOT).as_posix(),'sha256':sha(image)},profiles={'templates':'runtime-loaded version3 assets, not file-backed o2','action_rows':64,'action_base':'0x719a60','styles':[0,1]},ranges={hex(at):{'bytes':size,'sha256':hashlib.sha256(read(at,size)).hexdigest()}for at,size in [(0x719a60,64*68),(0x740440,56)]},output_path=target.relative_to(ROOT).as_posix(),output_sha256=sha(target),generator_sha256=sha(Path(__file__)))
 (out/'receipt.json').write_text(json.dumps(r,indent=2)+'\n');print(json.dumps(r))
if __name__=='__main__':main()
